// 클라이언트: 재시도해도 같은 키 (한 번 만들어 재시도 내내 유지)
const key = crypto.randomUUID();
async function pay() {
  return fetch('/payments', {
    method: 'POST',
    headers: { 'Idempotency-Key': key },   // 재시도 시에도 같은 key
    body: JSON.stringify({ amount: 500 }),
  });
}
// 서버: key 를 보고 이미 처리했으면 저장된 응답을 그대로 반환
